<?php get_header();while(have_posts()):the_post();$url=get_post_meta(get_the_ID(),'_affiliate_url',true);$sale=get_post_meta(get_the_ID(),'_sale_price',true);$regular=get_post_meta(get_the_ID(),'_regular_price',true);$video=get_post_meta(get_the_ID(),'_video_url',true);?><main class="dn-wrap dn-hero"><article><h1><?php the_title(); ?></h1><?php if(has_post_thumbnail())the_post_thumbnail('large',array('style'=>'max-width:100%;height:auto;border-radius:16px'));?><div style="margin-top:20px"><?php the_content(); ?></div><?php if($sale): ?><div class="dn-price"><?php echo esc_html($sale); ?><?php if($regular): ?><span class="dn-old"><?php echo esc_html($regular); ?></span><?php endif; ?></div><?php endif; ?><?php if($url): ?><a class="dn-buy" href="<?php echo esc_url($url); ?>" target="_blank" rel="sponsored noopener">View Deal →</a><?php endif; ?><?php if($video): ?><div style="margin-top:25px"><video controls preload="metadata" style="width:100%;max-width:900px;border-radius:14px"><source src="<?php echo esc_url($video); ?>"></video></div><?php endif; ?></article></main><?php endwhile;get_footer(); ?>
